class Solution(object):
    def singleNumber(self, nums):
        res = 0
        for n in nums: res ^= n
        return res

class Solution(object):
    def findTheDifference(self, s, t):
        res = 0
        for c in s + t: res ^= ord(c)
        return chr(res)

class Solution(object):
    def addDigits(self, num):
        if num == 0: return 0
        return 1 + (num - 1) % 9
